        if ((emon.Port.CellsAt(et, ts) != 91) || (emon.Port.CellsAt(et, ts + (n - 1)) != 93)) {
            return 0 == 1;
        }
        while (j < (n - 1)) {
            int c = emon.Port.CellsAt(et, ts + j);
            if ((c < 48) || (c > 57)) {
                return 0 == 1;
            }
            j += 1;
