    internal static int PaHeadingNumber(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, int par, int from, int to, emon.Port.Cells hc, int hl) {
