            j += 1;
        }
        emon.Port.CellsDrop(raw, n - d);
        while (k < (emon.Port.CellsLen(fr) / FrStride)) {
            int s = emon.Port.CellsAt(fr, (k * FrStride) + 5);
            if (s >= b) {
                emon.Port.CellsSet(fr, (k * FrStride) + 5, s - d);
            }
            if ((s > a) && (s < b)) {
                emon.Port.CellsSet(fr, (k * FrStride) + 5, a);
            }
            k += 1;
        }
        return 0;
    }
    internal static int PaScrub(emon.Port.Cells raw, emon.Port.Cells fr, int from) {
        // Cut every list, note or caption group at or after `from`: the stages leave one only at a paragraph's start.
        int i = from;
        while (i < emon.Port.CellsLen(raw)) {
            int c = emon.Port.CellsAt(raw, i);
            int n = emon.Port.CellsLen(raw);
            if ((c == Lists.LsSItem()) || ((c == Lists.LsSNote()) || (c == Lists.LsSCap()))) {
                int gend = PaGroupEnd(raw, i, n);
                if (gend > 0) {
                    if ((gend < n) && (emon.Port.CellsAt(raw, gend) == 32)) {
                        PaCut(raw, fr, i, gend + 1);
                    } else {
                        PaCut(raw, fr, i, gend);
                    }
                } else {
                    i += 1;
                }
            } else {
                i += 1;
            }
        }
        return 0;
    }
    internal static int PaHasRef(emon.Port.Cells raw, int from, int to) {
        // 1 when the range holds a note reference group.
        int i = from;
        while (i < to) {
            if (emon.Port.CellsAt(raw, i) == Lists.LsSRef()) {
                return 1;
            }
            i += 1;
        }
        return 0;
    }
    internal static int PaTextChild(emon.Port.Cells nodes, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, int par, int from, int to) {
        // A `text` inline of the paragraph for raw[from..to), normalised. Answers its node.
        int child = Model.NodeNew(nodes, Model.NkText(), par);
        int t0 = emon.Port.CellsLen(text);
        Normalize.NzNfc(raw, from, to, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
        Model.NodeSetText(nodes, child, t0, emon.Port.CellsLen(text) - t0);
        Model.NodeSetConf(nodes, child, 1000);
        Model.NodeAddSrc(nodes, child, Model.SrText());
        return child;
    }
    internal static int PaSpanNode(emon.Port.Cells nodes, int par, int bits) {
        // A `span` inline of the style bits under par (P4.7, D192); -1 when the Model's depth limit says no.
        int sp = Model.NodeNew(nodes, Model.NkSpan(), par);
        if (sp < 0) {
            return -1;
        }
        Model.NodeSetSub(nodes, sp, bits);
        Model.NodeSetConf(nodes, sp, 900);
        Model.NodeAddSrc(nodes, sp, Model.SrText());
        return sp;
    }
    internal static int PaLinkNode(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells hc, int par, int id) {
        // A `link` inline for link `id` of the block in `hc` (`emon.inline`) under par: a URI is its `href`; an internal
        // link holds its destination (the page + 1 in `sub`, the point packed in `aux`) until `emon.restruct` finds the block
        // it names and makes it the `target`. -1 when the Model's depth limit says no.
        int lk = Model.NodeNew(nodes, Model.NkLink(), par);
        if (lk < 0) {
            return -1;
        }
        Model.NodeAddSrc(nodes, lk, Model.SrAnnot());
        if (Inline.IlLinkGet(hc, id, 0) == 1) {
            Model.NodeSetConf(nodes, lk, 1000);
            Model.NodeSetAttrText(nodes, attrs, lk, Model.FkHref(), Inline.IlLinkGet(hc, id, 1), Inline.IlLinkGet(hc, id, 2));
        } else {
            Model.NodeSetConf(nodes, lk, 700);
            Model.NodeAddSrc(nodes, lk, Model.SrInfer());
            Model.NodeSetSub(nodes, lk, Inline.IlLinkGet(hc, id, 3) + 1);
            Model.NodeSetAux(nodes, lk, Inline.IlLinkGet(hc, id, 4));
        }
        return lk;
    }
    internal static int PaInlines(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, int par, int from, int to, int @base, emon.Port.Cells hc) {
        // The inline children of the paragraph for raw[from..to): `text` runs, in a `span` where the style is marked and a
        // `link` where the text is under one (`emon.inline`, P4.7: a marker in the text is a change of state, `base` the
        // style the paragraph is set in, which is not marked), and a `ref` for every note reference group (its marker;
        // the target is set later, when the notes are known). A space before a reference is not text: the reference
        // stands where the marker was printed, against the word. A reference ends the span and the link it is in. Answers
        // the first child that is not a `ref`, -1 when there is none.
        int i = from;
        int seg = from;
        int first = -1;
        int child = 0;
        int st = Inline.IlStateAt(raw, from);
        int cl = 0;
        int cb = 0;
        int lk = -1;
        int sp = -1;
        int pp = 0;
        int ev = 0;
        int ge = 0;
        int sep = 0;
        int se = 0;
        int eff = 0;
        while (i <= to) {
            ev = 0;
            if (i == to) {
                ev = 3;
            } else {
                int c = emon.Port.CellsAt(raw, i);
                if (c == Inline.IlSSty()) {
                    ge = Inline.IlMarkEnd(raw, i, to);
                    if (ge > 0) {
                        ev = 1;
                    }
                }
                if (c == Lists.LsSRef()) {
                    ge = PaGroupEnd(raw, i, to);
                    sep = -1;
                    if (ge > 0) {
                        sep = PaGroupSep(raw, i, ge);
                    }
                    if (sep >= 0) {
                        ev = 2;
                    }
                }
            }
            if (ev == 0) {
                i += 1;
            } else {
                se = i;
                if ((ev == 2) && (se > seg) && (emon.Port.CellsAt(raw, se - 1) == 32)) {
                    se -= 1;
                }
                if (se > seg) {
                    eff = Inline.IlEff(st, @base);
                    if (Inline.IlLink(eff) != cl) {
                        cl = Inline.IlLink(eff);
                        cb = 0;
                        sp = -1;
                        lk = -1;
                        if (cl > 0) {
                            lk = PaLinkNode(nodes, attrs, hc, par, cl - 1);
                            if ((lk >= 0) && (first < 0)) {
                                first = lk;
                            }
                        }
                    }
                    pp = par;
                    if (lk >= 0) {
                        pp = lk;
                    }
                    if (Inline.IlBits(eff) != cb) {
                        cb = Inline.IlBits(eff);
                        sp = -1;
                        if (cb > 0) {
                            sp = PaSpanNode(nodes, pp, cb);
                            if ((sp >= 0) && (lk < 0) && (first < 0)) {
                                first = sp;
                            }
                        }
                    }
                    if (sp >= 0) {
                        pp = sp;
                    }
                    child = PaTextChild(nodes, text, raw, tmp, pp, seg, se);
                    if ((sp < 0) && (lk < 0) && (first < 0)) {
                        first = child;
                    }
                }
                if (ev == 1) {
                    st = Inline.IlMarkValue(raw, i, ge);
                    i = ge;
                    seg = ge;
                }
                if (ev == 2) {
                    cl = 0;
                    cb = 0;
                    lk = -1;
                    sp = -1;
                    child = Model.NodeNew(nodes, Model.NkRef(), par);
                    Model.NodeSetConf(nodes, child, 500);
                    Model.NodeAddSrc(nodes, child, Model.SrText());
                    Model.NodeAddSrc(nodes, child, Model.SrInfer());
                    PaPutMarker(nodes, attrs, text, raw, child, Model.FkMarker(), sep + 1, ge - 1);
                    i = ge;
                    seg = ge;
                }
                if (ev == 3) {
                    i = to + 1;
                }
            }
        }
        return first;
    }
    internal static int PaCompact(emon.Port.Cells raw, emon.Port.Cells fr) {
        // Take every style marker out of raw in one pass, and move the raw starts of the fragments (`fr`, cell 5 of a row,
        // ascending) with it.
        int n = emon.Port.CellsLen(raw);
        int nfr = emon.Port.CellsLen(fr) / FrStride;
        int i = 0;
        int o = 0;
        int k = 0;
        int ge = 0;
        while (i < n) {
            while ((k < nfr) && (emon.Port.CellsAt(fr, (k * FrStride) + 5) <= i)) {
                emon.Port.CellsSet(fr, (k * FrStride) + 5, o);
                k += 1;
            }
            ge = -1;
            if (emon.Port.CellsAt(raw, i) == Inline.IlSSty()) {
                ge = Inline.IlMarkEnd(raw, i, n);
            }
            if (ge > 0) {
                i = ge;
            } else {
                emon.Port.CellsSet(raw, o, emon.Port.CellsAt(raw, i));
                o += 1;
                i += 1;
            }
        }
        while (k < nfr) {
            emon.Port.CellsSet(fr, (k * FrStride) + 5, o);
            k += 1;
        }
        emon.Port.CellsDrop(raw, o);
        return 0;
    }
    internal static int PaFlush(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells al, emon.Port.Cells hc, int parent) {
        // Close the open paragraph, if there is one, under `parent`: its node, `at` one region per fragment (a
        // column or a page), `src`, `conf`. The text is the paragraph's own when it is on one page, else a `text`
        // inline per page it is on with a `break` milestone between two, a column break being only a new region
        // (SPEC 10.1.2). Under the root (parent 0) a paragraph the heading analysis found a heading in is a `heading` of its
        // level under the open section it belongs in (D167). A paragraph that an initial opens (`fr`'s first row, P4.10) has an
        // `initial` inline first, holding the initial's text, and the rest of its text as a `text` inline (also when it is on one
        // page, where it has its own `text` as well, equal to the two); no list, note or caption group is read there (the
        // initial wins, D229). A paragraph that starts with a group of the list, note or caption stage is an `item`, a `note`
        // holding a paragraph, or a `caption` (D179), the group's marker or label an attribute and not in the text; note
        // reference groups in the text become `ref` inlines. Closes the block's line rows in `al` (P4.11: `al-mark`,
        // `al-pass` decides at the end). Empties `raw` and `fr`.
        int nfr = emon.Port.CellsLen(fr) / FrStride;
        int rawn = emon.Port.CellsLen(raw);
        if (nfr == 0) {
            emon.Port.CellsDrop(raw, 0);
            return 0;
        }
        int hl = emon.Port.CellsAt(fr, 6);
        int ncp = emon.Port.CellsAt(fr, FrNcp);
        int lev = 0;
        int sect = parent;
        int kind = Model.NkParagraph();
        int par = 0;
        int own = -1;
        int lead = 0;
        int gcode = 0;
        int gval = 0;
        int gm0 = 0;
        int gm1 = 0;
        int blk = 0;
        int k = 0;
        int kend = 0;
        int runs = 1;
        int from = 0;
        int to = 0;
        int cut = 0;
        int ini = 0;
        int t0 = 0;
        int child = 0;
        int sbase = 0;
        int sty = 0;
        int kids = 0;
        // style markers (P4.7): written, or, when nothing in the paragraph is marked against its own style, taken out
        if (Inline.IlHas(raw, rawn) == 1) {
            sbase = Inline.IlBaseOf(raw, rawn);
            sty = Inline.IlStyled(raw, rawn, sbase);
            if (sty == 0) {
                PaCompact(raw, fr);
                rawn = emon.Port.CellsLen(raw);
            }
        }
        if (parent == 0) {
            lev = Heading.HdLevel(hc, hl);
            sect = Heading.HdParent(hc, nodes, lev);
        }
        // a group at the start of the paragraph: an item, a note body or a caption (not inside a margin note)
        if ((lev == 0) && ((rawn > 0) && (ncp == 0))) {
            int c0 = emon.Port.CellsAt(raw, emon.Port.CellsAt(fr, 5));
            int s0 = emon.Port.CellsAt(fr, 5);
            if ((c0 == Lists.LsSItem()) || ((c0 == Lists.LsSNote()) || (c0 == Lists.LsSCap()))) {
                int gend = PaGroupEnd(raw, s0, rawn);
                int sep = PaGroupSep(raw, s0, gend);
                if ((gend > 0) && (sep > 0) && ((parent == 0) || (Model.NodeKind(nodes, parent) != Model.NkNote()))) {
                    gcode = emon.Port.CellsAt(raw, s0 + 1) - Lists.LsSBase();
                    gval = PaGroupValue(raw, s0, sep);
                    gm0 = sep + 1;
                    gm1 = gend - 1;
                    lead = gend - s0;
                    if ((gend < rawn) && (emon.Port.CellsAt(raw, gend) == 32)) {
                        lead += 1;
                    }
                    if (c0 == Lists.LsSItem()) {
                        blk = 1;
                    }
                    if (c0 == Lists.LsSNote()) {
                        blk = 2;
                    }
                    if (c0 == Lists.LsSCap()) {
                        blk = 3;
                    }
                } else {
                    // an unusable group (inside a margin note, or not closed): its text is dropped, the rest kept
                    if (gend > 0) {
                        lead = gend - s0;
                        if ((gend < rawn) && (emon.Port.CellsAt(raw, gend) == 32)) {
                            lead += 1;
                        }
                    }
                }
            }
        }
        // a group that is still in the text after the first is a stray (the stages put one only at a line's start, and
        // a paragraph's first line is its start): it is cut out, with its space
        PaScrub(raw, fr, emon.Port.CellsAt(fr, 5) + lead);
        rawn = emon.Port.CellsLen(raw);
        if (lev > 0) {
            kind = Model.NkHeading();
        }
        if (blk == 1) {
            kind = Model.NkItem();
        }
        if (blk == 3) {
            kind = Model.NkCaption();
        }
        if (blk == 2) {
            own = Model.NodeNew(nodes, Model.NkNote(), sect);
            sect = own;
        }
        par = Model.NodeNew(nodes, kind, sect);
        if (lev > 0) {
            Model.NodeSetSub(nodes, par, lev);
        }
        Model.NodeSetConf(nodes, par, 500);
        Model.NodeAddSrc(nodes, par, Model.SrText());
        Model.NodeAddSrc(nodes, par, Model.SrInfer());
        if (blk == 1) {
            Model.NodeSetSub(nodes, par, gcode);
            Model.NodeSetAux(nodes, par, gval);
            Model.NodeSetAttrInt(nodes, attrs, par, Model.FkBox(), Lists.LsGet(hc, hl, Lists.LsKTextx()));
            PaPutMarker(nodes, attrs, text, raw, par, Model.FkMarker(), gm0, gm1);
        }
        if (blk == 3) {
            Model.NodeSetAux(nodes, par, gcode);
            PaPutMarker(nodes, attrs, text, raw, par, Model.FkLabel(), gm0, gm1);
        }
        if (blk == 2) {
            Model.NodeSetSub(nodes, own, gcode);
            Model.NodeSetConf(nodes, own, 500);
            Model.NodeAddSrc(nodes, own, Model.SrInfer());
            PaPutMarker(nodes, attrs, text, raw, own, Model.FkMarker(), gm0, gm1);
        }
        k = 1;
        while (k < nfr) {
            if (emon.Port.CellsAt(fr, k * FrStride) != emon.Port.CellsAt(fr, (k - 1) * FrStride)) {
                runs += 1;
            }
            k += 1;
        }
        k = 0;
        while (k < nfr) {
            int pg = emon.Port.CellsAt(fr, k * FrStride);
            kend = k + 1;
            while ((kend < nfr) && (emon.Port.CellsAt(fr, kend * FrStride) == pg)) {
                kend += 1;
            }
            from = emon.Port.CellsAt(fr, (k * FrStride) + 5);
            if (k == 0) {
                from += lead;
            }
            to = rawn;
            if (kend < nfr) {
                to = emon.Port.CellsAt(fr, (kend * FrStride) + 5);
            }
            kids = 0;
            if (runs > 1) {
                kids = 1;
            }
            if ((k == 0) && (ncp > 0)) {
                kids = 1;
            }
            if (PaHasRef(raw, from, to) == 1) {
                kids = 1;
            }
            if (sty == 1) {
                kids = 1;
            }
            child = -1;
            if (kids == 1) {
                if ((runs > 1) && (k > 0)) {
                    int br = Model.NodeNew(nodes, Model.NkBreak(), par);
                    Model.NodeSetSub(nodes, br, pg);
                    Model.NodeSetConf(nodes, br, 500);
                    Model.NodeAddSrc(nodes, br, Model.SrInfer());
                }
                cut = from;
                if ((k == 0) && (ncp > 0)) {
                    cut = from + ncp;
                    if (cut > to) {
                        cut = to;
                    }
                    ini = Model.NodeNew(nodes, Model.NkInitial(), par);
                    Model.NodeSetSub(nodes, ini, emon.Port.CellsAt(fr, FrForm));
                    Model.NodeSetAux(nodes, ini, emon.Port.CellsAt(fr, FrLines));
                    Model.NodeSetConf(nodes, ini, 800);
                    if (emon.Port.CellsAt(fr, FrFlag) == 1) {
                        Model.NodeSetConf(nodes, ini, 500);
                        Model.NodeAddFlag(nodes, ini, Model.FlLowConf());
                    }
                    Model.NodeAddSrc(nodes, ini, Model.SrText());
                    Model.NodeAddSrc(nodes, ini, Model.SrInfer());
                    child = Model.NodeNew(nodes, Model.NkText(), ini);
                    t0 = emon.Port.CellsLen(text);
                    Normalize.NzNfc(raw, from, cut, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                    int tn0 = emon.Port.CellsLen(text) - t0;
                    Model.NodeSetText(nodes, child, t0, tn0);
                    Model.NodeSetConf(nodes, child, 1000);
                    Model.NodeAddSrc(nodes, child, Model.SrText());
                    child = -1;
                }
                if ((runs > 1) || (cut < to)) {
                    child = PaInlines(nodes, attrs, text, raw, tmp, par, cut, to, sbase, hc);
                }
                if ((runs > 1) && (child < 0) && (k == 0) && (ncp > 0)) {
                    child = PaTextChild(nodes, text, raw, tmp, par, cut, to);
                }
                if ((runs == 1) && ((sty == 0) && (PaHasRef(raw, from, to) == 0))) {
                    t0 = emon.Port.CellsLen(text);
                    Normalize.NzNfc(raw, from, to, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                    int tn1 = emon.Port.CellsLen(text) - t0;
                    Model.NodeSetText(nodes, par, t0, tn1);
                }
            } else {
                if (lev > 0) {
                    from += PaHeadingNumber(nodes, attrs, text, raw, tmp, par, from, to, hc, hl);
                }
                t0 = emon.Port.CellsLen(text);
                Normalize.NzNfc(raw, from, to, text, tmp, Normalize.NzFlagLigatures() + Normalize.NzFlagRadicals());
                int tn2 = emon.Port.CellsLen(text) - t0;
                Model.NodeSetText(nodes, par, t0, tn2);
            }
            while (k < kend) {
                int @base = k * FrStride;
                int rx0 = emon.Port.CellsAt(fr, @base + 1);
                int ry0 = emon.Port.CellsAt(fr, @base + 2);
                int rx1 = emon.Port.CellsAt(fr, @base + 3);
                int ry1 = emon.Port.CellsAt(fr, @base + 4);
                Model.NodeAddRegion(nodes, regions, par, pg, rx0, ry0, rx1, ry1);
                if (own >= 0) {
                    Model.NodeAddRegion(nodes, regions, own, pg, rx0, ry0, rx1, ry1);
                }
                if ((runs > 1) && (child >= 0)) {
                    Model.NodeAddRegion(nodes, regions, child, pg, rx0, ry0, rx1, ry1);
                }
                k += 1;
            }
        }
        Align.AlMark(al, par);
        emon.Port.CellsDrop(raw, 0);
        emon.Port.CellsDrop(fr, 0);
        return 0;
    }
    internal static int PaMilestone(emon.Port.Cells nodes, int page, emon.Port.Cells hc) {
        // A page milestone between two blocks, in the open section when there is one (D167).
        int b = Model.NodeNew(nodes, Model.NkBreak(), Heading.HdCur(hc));
        Model.NodeSetSub(nodes, b, page);
        Model.NodeSetConf(nodes, b, 500);
        Model.NodeAddSrc(nodes, b, Model.SrInfer());
        return 0;
    }
    internal static bool PaLetter(int cp) {
        // A letter, for the hyphen at a break: Basic Latin, Latin-1, Greek, Cyrillic, and anything above U+2FF
        // that is not punctuation or a symbol (the CJK block and beyond).
        if ((cp >= 65) && (cp <= 90)) {
            return 1 == 1;
        }
        if (PaLower(cp)) {
            return 1 == 1;
        }
        if ((cp >= 192) && (cp <= 591)) {
            return 1 == 1;
        }
        if ((cp >= 880) && (cp <= 1327)) {
            return 1 == 1;
        }
        return 0 == 1;
    }
    internal static bool PaBullet(int cp) {
        // A bullet or a dash that stands alone as a word: a list marker.
        if ((cp == 8226) || (cp == 183) || (cp == 9679)) {
            return 1 == 1;
        }
        if ((cp == 9632) || (cp == 9642) || (cp == 8259)) {
            return 1 == 1;
        }
        if ((cp == 42) || (cp == 45) || (cp == 8211) || (cp == 8212)) {
            return 1 == 1;
        }
        return 0 == 1;
    }
    internal static bool PaMarker(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, int l) {
        // Does the line start with a list marker: a bullet or dash alone, `1.`, `12)`, `a)`, `(a)`.
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int wn = Evidence.LnGet(ln, l, Evidence.LhCount());
        if (wn < 1) {
            return 0 == 1;
        }
        int ts = Evidence.WdGet(wd, w0, Evidence.HdTstart());
        int tl = Evidence.WdGet(wd, w0, Evidence.HdTlen());
        if ((ts < 0) || (tl < 1)) {
            return 0 == 1;
        }
        int c0 = emon.Port.CellsAt(et, ts);
        if (tl == 1) {
            return PaBullet(c0);
        }
        if (tl > 5) {
            return 0 == 1;
        }
        int cl = emon.Port.CellsAt(et, ts + (tl - 1));
        if ((c0 >= 48) && (c0 <= 57)) {
            if ((cl != 46) && (cl != 41)) {
                return 0 == 1;
            }
            int k = 1;
            while (k < (tl - 1)) {
                int c = emon.Port.CellsAt(et, ts + k);
                if ((c < 48) || (c > 57)) {
                    return 0 == 1;
                }
                k += 1;
            }
            return 1 == 1;
        }
        if ((c0 == 40) && (cl == 41) && (tl == 3)) {
            return 1 == 1;
        }
        if ((tl == 2) && PaLetter(c0) && (cl == 41)) {
            return 1 == 1;
        }
        return 0 == 1;
    }
    internal static int PaBottom(emon.Port.Cells cf, int r) {
        // The bottom a fragment's last line is compared with: the bottom of the region its vertical cuts came from, so
        // the columns of one set (side by side, whatever else lies above or below beside them) end together.
        return emon.Port.CellsAt(cf, (r * CfStride) + CfRef);
    }
    internal static int PaMaxi(int a, int b) {
        if (a > b) {
            return a;
        }
        return b;
    }
    internal static int PaOpenNote(emon.Port.Cells raw, emon.Port.Cells fr) {
        // 1 when the open paragraph (its text so far in `raw`, its fragments in `fr`) begins with a note body's group: a footnote or an endnote.
        if (emon.Port.CellsLen(fr) < FrStride) {
            return 0;
        }
        int s0 = emon.Port.CellsAt(fr, 5);
        if (s0 >= emon.Port.CellsLen(raw)) {
            return 0;
        }
        if (emon.Port.CellsAt(raw, s0) == Lists.LsSNote()) {
            return 1;
        }
        return 0;
    }
    internal static int PaJoinScore(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells raw, int a, int b, int colx0, int colx1, int ncol, int bmargin, int indents, int bottom, int bx0, int bx1, int bn, emon.Port.Cells hc, int note) {
        // The points for the paragraph that ended its fragment (its last line a, the text so far in `raw`) going
        // on with line b, the first of the next fragment (SPEC 10.1.2, D164). `colx0`..`colx1` is the extent of a's
        // fragment, `ncol` its lines (the edge signals need two), `bmargin` the margin of b's, `indents` whether
        // the document's paragraphs have first-line indents, `bottom` the bottom of the fragments of a's band.
        // `note` is 1 when the paragraph is a note body (P12.7, smoke B N1): a footnote goes on in type of its own size, and the body type of the next column or page is not its continuation.
        int n = emon.Port.CellsLen(raw);
        int sa = PaSize(wd, ln, a);
        int sb = PaSize(wd, ln, b);
        int pts = 0;
        if (n < 1) {
            return -100;
        }
        if ((Heading.HdLevel(hc, a) > 0) || (Heading.HdLevel(hc, b) > 0)) {
            return -100;
        }
        if (Lists.LsStart(hc, b) == 1) {
            return -100;
        }
        if ((note == 1) && ((PaAbs(sa - sb) * PaSizeDiv) > sa)) {
            return -100;
        }
        int last = emon.Port.CellsAt(raw, n - 1);
        if (((last == 45) || (last == 173)) && (n >= 2)) {
            if (PaLetter(emon.Port.CellsAt(raw, n - 2))) {
                pts += JsHyphen;
            }
        }
        if (ncol >= 2) {
            if (((colx1 - Evidence.LnGet(ln, a, Evidence.LhX1())) * 100) <= (PaEdgePct * (colx1 - colx0))) {
                pts += JsEdge;
            }
            if (((colx1 - Evidence.LnGet(ln, a, Evidence.LhX1())) * 5) > (colx1 - colx0)) {
                pts += JsShort;
            }
        }
        if (!PaEndsSentence(raw)) {
            pts += JsNoterm;
        }
        if (PaLower(PaFirstCp(wd, ln, et, b))) {
            pts += JsLower;
        }
        if ((indents == 1) && (((PaStart(ln, b) - bmargin) * PaIndentDiv) > sb) && (Lists.LsHangCol(hc, ln, a, b, colx0, bmargin) == 0)) {
            pts += JsIndent;
        }
        if (PaMarker(wd, ln, et, b)) {
            pts += JsMarker;
        }
        if (((PaAbs(sa - sb) * PaSizeDiv) > sa) || PaStyleDiffers(wd, ln, a, b, !PaEndsSentence(raw))) {
            pts += JsStyle;
        }
        if ((Evidence.LnGet(ln, a, Evidence.LhFirst()) + Evidence.LnGet(ln, a, Evidence.LhCount())) == Evidence.LnGet(ln, b, Evidence.LhFirst())) {
            pts += JsStream;
        }
        if ((ncol >= 2) && ((Evidence.LnGet(ln, a, Evidence.LhY1()) + (sa / 2)) >= bottom)) {
            pts += JsBottom;
        }
        if ((ncol >= 3) && (bn >= 3) && ((PaAbs((colx1 - colx0) - (bx1 - bx0)) * 4) > (PaMaxi(colx1 - colx0, bx1 - bx0) - 0))) {
            pts += JsWidth;
        }
        return pts;
    }
    internal static int PaLive(emon.Port.Cells ln, emon.Port.Cells lo, int first, int cnt) {
        // How many lines at the head of the fragment lo[first, first+cnt) a table holds (D178): the column stage
        // sees every line of the page, tables included, so that what it makes of the rest is what it always made;
        // the lines a table holds are left out here, where the paragraphs are made.
        int k = 0;
        while ((k < cnt) && (Table.TbClaimed(ln, emon.Port.CellsAt(lo, first + k)) != 0)) {
            k += 1;
        }
        return k;
    }
    internal static int PaHeld(emon.Port.Cells ln, emon.Port.Cells lo, int first, int cnt) {
        // How many lines of the fragment lo[first, first+cnt) a table holds, wherever they stand in it (D504).
        int k = 0;
        int n = 0;
        while (k < cnt) {
            if (Table.TbClaimed(ln, emon.Port.CellsAt(lo, first + k)) != 0) {
                n += 1;
            }
            k += 1;
        }
        return n;
    }
    internal static int PaFreeWords(emon.Port.Cells ln, emon.Port.Cells lo, int first, int cnt) {
        // How many words the lines of the fragment lo[first, first+cnt) that no table holds have between them (D504).
        int k = 0;
        int n = 0;
        while (k < cnt) {
            int l = emon.Port.CellsAt(lo, first + k);
            if (Table.TbClaimed(ln, l) == 0) {
                n += Evidence.LnGet(ln, l, Evidence.LhCount());
            }
            k += 1;
        }
        return n;
    }
    internal static int PaNote(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells al, emon.Port.Cells ii, emon.Port.Cells cf, emon.Port.Cells lo, int r, int med, emon.Port.Cells hc) {
        // The side fragment (row r of `cf`) as a `note` block of its role, in the open section (D167; the root when none), its lines made
        // paragraphs as any fragment's (D113). A fragment a table holds in part whose lines left over are fewer than
        // three words is no note: its lines are paragraphs of the open section (parent 0), so that no word is lost (D504).
        int @base = r * CfStride;
        int first = emon.Port.CellsAt(cf, @base + CfFirst);
        int cnt = emon.Port.CellsAt(cf, @base + CfCount);
        int page = emon.Port.CellsAt(cf, @base + CfPage);
        int held = PaHeld(ln, lo, first, cnt);
        int free = PaFreeWords(ln, lo, first, cnt);
        int note = 0;
        int mg = PaFmargin(ln, lo, first, cnt);
        int lead = PaLive(ln, lo, first, cnt);
        int i = lead + 1;
        int prev = emon.Port.CellsAt(lo, first + lead);
        if ((held == 0) || (free >= 3)) {
            note = Model.NodeNew(nodes, Model.NkNote(), Heading.HdCur(hc));
            Model.NodeSetSub(nodes, note, emon.Port.CellsAt(cf, @base + CfRole));
            Model.NodeSetConf(nodes, note, 500);
            Model.NodeAddSrc(nodes, note, Model.SrInfer());
            Model.NodeAddRegion(nodes, regions, note, page, emon.Port.CellsAt(cf, @base + CfX0), emon.Port.CellsAt(cf, @base + CfY0), emon.Port.CellsAt(cf, @base + CfX1), emon.Port.CellsAt(cf, @base + CfY1));
        }
        emon.Port.CellsDrop(raw, 0);
        emon.Port.CellsDrop(fr, 0);
        PaFragOpen(fr, ln, page, prev, 0);
        PaIniStart(wd, ln, et, raw, fr, ii, prev);
        PaAddLine(wd, ln, et, raw, prev, hc, fr);
        PaAlAdd(wd, ln, al, prev, emon.Port.CellsAt(cf, @base + CfX0), emon.Port.CellsAt(cf, @base + CfX1));
        while (i < cnt) {
            int b = emon.Port.CellsAt(lo, first + i);
            // a line a table holds stays the table's cell (D504)
            if (Table.TbClaimed(ln, b) == 0) {
                if ((Initial.InRow(ln, b) >= 0) || PaNewPar(wd, ln, et, prev, b, med, mg, hc)) {
                    PaFlush(nodes, attrs, regions, text, raw, tmp, fr, al, hc, note);
                    PaFragOpen(fr, ln, page, b, 0);
                    PaIniStart(wd, ln, et, raw, fr, ii, b);
                } else {
                    PaJoin(wd, ln, et, raw, b);
                    PaFragExtend(fr, ln, b);
                }
                PaAddLine(wd, ln, et, raw, b, hc, fr);
                PaAlAdd(wd, ln, al, b, emon.Port.CellsAt(cf, @base + CfX0), emon.Port.CellsAt(cf, @base + CfX1));
                prev = b;
            }
            i += 1;
        }
        PaFlush(nodes, attrs, regions, text, raw, tmp, fr, al, hc, note);
        return 0;
    }
    internal static int PaNotes(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells al, emon.Port.Cells ii, emon.Port.Cells cf, emon.Port.Cells lo, int med, int from, int cur, int ty, emon.Port.Cells hc) {
        // Write the side fragments that have been read to: those beside a body fragment before row `cur`, and
        // those beside `cur` that begin at or above y `ty`, each once, in the order of `cf`, after the paragraph
        // that was open where they begin (D111). Scans from row `from`; answers the first side row not written yet
        // (the row count when none).
        int nf = emon.Port.CellsLen(cf) / CfStride;
        int r = from;
        int pend = nf;
        while (r < nf) {
            int @base = r * CfStride;
            if ((emon.Port.CellsAt(cf, @base + CfRole) != Model.RlBody()) && (emon.Port.CellsAt(cf, @base + CfDone) == 0)) {
                if ((emon.Port.CellsAt(cf, @base + CfAssoc) < cur) || ((emon.Port.CellsAt(cf, @base + CfAssoc) == cur) && (emon.Port.CellsAt(cf, @base + CfY0) <= ty))) {
                    emon.Port.CellsSet(cf, @base + CfDone, 1);
                    // a side fragment every line of which a table holds is the table's cells, not a note (a narrow last column;
                    // D459 for a scan, D469 for a text layer too); one that a table holds in part is a note of the lines it does
                    // not; when those are fewer than three words they are body text, a paragraph of their own, and
                    // not a note, so that no word is lost (D504).
                    if (PaHeld(ln, lo, emon.Port.CellsAt(cf, @base + CfFirst), emon.Port.CellsAt(cf, @base + CfCount)) < emon.Port.CellsAt(cf, @base + CfCount)) {
                        PaNote(wd, ln, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, r, med, hc);
                    }
                } else if (pend > r) {
                    pend = r;
                }
            }
            r += 1;
        }
        return pend;
    }
    internal static int PaClose(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells al, emon.Port.Cells ii, emon.Port.Cells cf, emon.Port.Cells lo, emon.Port.Cells dq, int med, int from, int cur, int ty, int beforePage, emon.Port.Cells hc) {
        // Close the open paragraph, then write the side fragments that were read to (`pa-notes`), then make a
        // paragraph of each line queued in `dq` (the lines that are not upright, D136) and empty the queue.
        // Answers the first side row not written yet.
        int nq = emon.Port.CellsLen(dq);
        int nf = emon.Port.CellsLen(cf) / CfStride;
        int k = 0;
        int kept = 0;
        int pend = 0;
        int now = 0;
        PaFlush(nodes, attrs, regions, text, raw, tmp, fr, al, hc, 0);
        pend = PaNotes(wd, ln, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, med, from, cur, ty, hc);
        // P12.7 (smoke A N4): a line that is not upright (a label turned a quarter, in a form's margin) is written where its top is: before the first paragraph that starts at or below it on its page (`ty` the top
        // of the line that starts the next paragraph), not after the page's last; all of them when the close is the page's end (`cur` past the fragments)
        while (k < nq) {
            int l = emon.Port.CellsAt(dq, k);
            int pg = Evidence.LnGet(ln, l, Evidence.LhPage());
            now = 1;
            if (cur < nf) {
                now = 0;
                if (pg < emon.Port.CellsAt(cf, (cur * CfStride) + CfPage)) {
                    now = 1;
                }
                if ((pg == emon.Port.CellsAt(cf, (cur * CfStride) + CfPage)) && (Evidence.LnGet(ln, l, Evidence.LhY0()) <= ty)) {
                    now = 1;
                }
            }
            // The next page cannot emit queued lines until its page milestone has been written.
            if ((beforePage > 0) && (pg >= beforePage)) {
                now = 0;
            }
            if (now == 1) {
                PaFragOpen(fr, ln, pg, l, 0);
                PaAddLine(wd, ln, et, raw, l, hc, fr);
                PaFlush(nodes, attrs, regions, text, raw, tmp, fr, al, hc, 0);
            } else {
                emon.Port.CellsSet(dq, kept, l);
                kept += 1;
            }
            k += 1;
        }
        emon.Port.CellsDrop(dq, kept);
        return pend;
    }
    internal static int PaUprightCount(emon.Port.Cells ln, emon.Port.Cells ord) {
        // How many lines at the head of the sorted `ord` are upright (`pa-before` puts them first).
        int n = emon.Port.CellsLen(ord);
        int i = 0;
        while (i < n) {
            int l = emon.Port.CellsAt(ord, i);
            if (!PaUpright(ln, l)) {
                return i;
            }
            i += 1;
        }
        return n;
    }
    internal static int PaLayout(emon.Port.Cells cf, int r0, int r1, int page, emon.Port.Cells pages, emon.Port.Cells layout) {
        // The page's `layout` (D111): one cell per (band, col) of the fragments cf[r0..r1), its box the union of
        // theirs (the margin notes of a side, several fragments, are one column).
        int r = r0;
        int q = 0;
        int dup = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        while (r < r1) {
            int b = r * CfStride;
            int band = emon.Port.CellsAt(cf, b + CfBand);
            int col = emon.Port.CellsAt(cf, b + CfCol);
            dup = 0;
            q = r0;
            while (q < r) {
                if ((emon.Port.CellsAt(cf, (q * CfStride) + CfBand) == band) && (emon.Port.CellsAt(cf, (q * CfStride) + CfCol) == col)) {
                    dup = 1;
                }
                q += 1;
            }
            if (dup == 0) {
                x0 = emon.Port.CellsAt(cf, b + CfX0);
                y0 = emon.Port.CellsAt(cf, b + CfY0);
                x1 = emon.Port.CellsAt(cf, b + CfX1);
                y1 = emon.Port.CellsAt(cf, b + CfY1);
                q = r + 1;
                while (q < r1) {
                    if ((emon.Port.CellsAt(cf, (q * CfStride) + CfBand) == band) && (emon.Port.CellsAt(cf, (q * CfStride) + CfCol) == col)) {
                        if (emon.Port.CellsAt(cf, (q * CfStride) + CfX0) < x0) {
                            x0 = emon.Port.CellsAt(cf, (q * CfStride) + CfX0);
                        }
                        if (emon.Port.CellsAt(cf, (q * CfStride) + CfY0) < y0) {
                            y0 = emon.Port.CellsAt(cf, (q * CfStride) + CfY0);
                        }
                        if (emon.Port.CellsAt(cf, (q * CfStride) + CfX1) > x1) {
                            x1 = emon.Port.CellsAt(cf, (q * CfStride) + CfX1);
                        }
                        if (emon.Port.CellsAt(cf, (q * CfStride) + CfY1) > y1) {
                            y1 = emon.Port.CellsAt(cf, (q * CfStride) + CfY1);
                        }
                    }
                    q += 1;
                }
                Model.LayAdd(layout, pages, page - 1, band, col, emon.Port.CellsAt(cf, b + CfRole), x0, y0, x1, y1);
            }
            r += 1;
        }
        return 0;
    }
    internal static int PaColumns(emon.Port.Cells wd, emon.Port.Cells et, int npages, emon.Port.Cells pages, emon.Port.Cells layout, emon.Port.Cells lt, emon.Port.Cells ord, emon.Port.Cells ls, emon.Port.Cells sd, emon.Port.Cells it, emon.Port.Cells io, emon.Port.Cells rw, emon.Port.Cells gu, emon.Port.Cells ac, emon.Port.Cells tm, emon.Port.Cells cf, emon.Port.Cells lo, emon.Port.Cells pr) {
        // Phase one: every page's column fragments (`emon.columns`), and the page `layout` (D111) from them.
        int p = 1;
        int i = 0;
        int nu = 0;
        emon.Port.CellsDrop(cf, 0);
        emon.Port.CellsDrop(lo, 0);
        while (p <= npages) {
            PaCollect(ord, lt, p);
            nu = PaUprightCount(lt, ord);
            emon.Port.CellsDrop(ls, 0);
            i = 0;
            while (i < nu) {
                emon.Port.CellsPush(ls, emon.Port.CellsAt(ord, i));
                i += 1;
            }
            int r0 = emon.Port.CellsLen(cf) / CfStride;
            Columns.LcPage(wd, et, lt, p, ls, sd, it, io, rw, gu, ac, tm, cf, lo, pr);
            PaLayout(cf, r0, emon.Port.CellsLen(cf) / CfStride, p, pages, layout);
            p += 1;
        }
        return 0;
    }
    internal static int PaTables(emon.Port.Cells tb, int tcur, int p, int ymid2, int lb, emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tq, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells ledger, emon.Port.Cells hc) {
        // Emit, in document order, the tables of page p from `tcur` on whose top is at or above `ymid2` (twice
        // a baseline y: the order key of `pa-ymid2`). The open paragraph has been closed. Answers the next table
        // to emit (P5.1: a table is a block, found before this and placed here by its top, D178).
        int k = tcur;
        while (Table.TbDueFor(tb, k, p, ymid2, ln, lb)) {
            Table.TbEmit(tb, k, Heading.HdCur(hc), wd, et, ln, tc, tw, tq, nodes, attrs, regions, text, raw, tmp, ledger);
            k += 1;
        }
        emon.Port.CellsDrop(raw, 0);
        return k;
    }
    public static int PaBuild(emon.Port.Cells wd, emon.Port.Cells et, int npages, emon.Port.Cells pages, emon.Port.Cells layout, emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells ord, emon.Port.Cells raw, emon.Port.Cells tmp, emon.Port.Cells fr, emon.Port.Cells gp, emon.Port.Cells lt, emon.Port.Cells ls, emon.Port.Cells sd, emon.Port.Cells it, emon.Port.Cells io, emon.Port.Cells rw, emon.Port.Cells gu, emon.Port.Cells ac, emon.Port.Cells tm, emon.Port.Cells cf, emon.Port.Cells lo, emon.Port.Cells pr, emon.Port.Cells dbg, emon.Port.Cells hc, emon.Port.Cells tb, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells tq, emon.Port.Cells ledger, emon.Port.Cells ii, emon.Port.Cells al) {
        // Tables (`tb tc tw tq`, `emon.table`) are placed between the paragraphs by their tops; a line a table
        // holds is not in the reading order at all.
        // Append every page's lines to the Model as paragraphs under the document root (node 0, made by
        // `model-init`), in the reading order of `emon.columns`, and write each page's `layout`; `pages` is the
        // Model's page table (`pa-pages`). `lt` (the lines, copied), `ls sd it io rw gu ac tm cf lo pr` (the column
        // stage's), `ord raw tmp fr gp` are scratch (`gp` first holds the gaps, then the queue of lines that are not
        // upright). `dbg` is the debug log, the stage's evidence dump: every join decision, a row of eight (the
        // fragment, the lines a and b as rows of `lt`, the score, a's fragment x0 and x1, a's x1, its line count).
        // `hc` is the heading analysis (`emon.heading`, P4.4, D167): an EMPTY `hc` means none and the paragraphs are
        // what they were; it is also where the open sections are kept.
        // `lt` is PREPARED by the caller: the lines copied (`lc-copy`), the initials found in the copy (`in-detect`, P4.10:
        // before the style and heading analysis reads the lines, so a big first letter is never a heading), and `hc` made from
        // it; `ii` is the initials' table, `al` the open paragraph's alignment rows (P4.11). Answers 0.
        int med = 0;
        int indents = 0;
        int p = 1;
        int i = 0;
        int n = 0;
        int nu = 0;
        int nf = 0;
        int r = 0;
        int r1 = 0;
        int first = 0;
        int cnt = 0;
        int b = 0;
        int prev = -1;
        int prevfr = -1;
        int open = 0;
        int cont = 0;
        int pend = 0;
        int rs = 0;
        int mg = 0;
        int ty = 0;
        int tcur = 0;
        int k0 = 0;
        int opn = 0;
        int beforePage = 0;
        int score = 0;
        Initial.InRetire(lt, ii);
        PaColumns(wd, et, npages, pages, layout, lt, ord, ls, sd, it, io, rw, gu, ac, tm, cf, lo, pr);
        nf = emon.Port.CellsLen(cf) / CfStride;
        med = PaMedian(lt, cf, lo, gp);
        if (PaIndents(wd, lt, cf, lo) >= PaIndentUse) {
            indents = 1;
        }
        emon.Port.CellsDrop(gp, 0);
        emon.Port.CellsDrop(raw, 0);
        emon.Port.CellsDrop(fr, 0);
        emon.Port.CellsDrop(al, 0);
        emon.Port.CellsDrop(dbg, 0);
        while (p <= npages) {
            PaCollect(ord, lt, p);
            n = emon.Port.CellsLen(ord);
            nu = PaUprightCount(lt, ord);
            i = nu;
            while (i < n) {
                if (Table.TbClaimed(lt, emon.Port.CellsAt(ord, i)) == 0) {
                    emon.Port.CellsPush(gp, emon.Port.CellsAt(ord, i));
                }
                i += 1;
            }
            tcur = Table.TbSkip(tb, tcur, p);
            while ((r < nf) && (emon.Port.CellsAt(cf, (r * CfStride) + CfPage) < p)) {
                r += 1;
            }
            r1 = r;
            while ((r1 < nf) && (emon.Port.CellsAt(cf, (r1 * CfStride) + CfPage) == p) && (emon.Port.CellsAt(cf, (r1 * CfStride) + CfRole) == Model.RlBody())) {
                r1 += 1;
            }
            if (r == r1) {
                pend = PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, nf, 1000000000, p, hc);
                open = 0;
                prev = -1;
                if (p > 1) {
                    PaMilestone(nodes, p, hc);
                }
                pend = PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, nf, 1000000000, 0, hc);
                tcur = PaTables(tb, tcur, p, PaAll, -1, wd, lt, et, tc, tw, tq, nodes, attrs, regions, text, raw, tmp, ledger, hc);
            } else {
                i = r;
                while (i < r1) {
                    first = emon.Port.CellsAt(cf, (i * CfStride) + CfFirst);
                    cnt = emon.Port.CellsAt(cf, (i * CfStride) + CfCount);
                    k0 = PaLive(lt, lo, first, cnt);
                    first += k0;
                    cnt -= k0;
                    if (cnt > 0) {
                        mg = PaFmargin(lt, lo, first, cnt);
                        b = emon.Port.CellsAt(lo, first);
                        cont = 0;
                        if (open == 1) {
                            opn = PaOpenNote(raw, fr);
                            score = PaJoinScore(wd, lt, et, raw, prev, b, emon.Port.CellsAt(cf, (prevfr * CfStride) + CfX0), emon.Port.CellsAt(cf, (prevfr * CfStride) + CfX1), emon.Port.CellsAt(cf, (prevfr * CfStride) + CfCount), mg, indents, PaBottom(cf, prevfr), emon.Port.CellsAt(cf, (i * CfStride) + CfX0), emon.Port.CellsAt(cf, (i * CfStride) + CfX1), emon.Port.CellsAt(cf, (i * CfStride) + CfCount), hc, opn);
                            emon.Port.CellsPush(dbg, i);
                            emon.Port.CellsPush(dbg, prev);
                            emon.Port.CellsPush(dbg, b);
                            emon.Port.CellsPush(dbg, score);
                            emon.Port.CellsPush(dbg, emon.Port.CellsAt(cf, (prevfr * CfStride) + CfX0));
                            emon.Port.CellsPush(dbg, emon.Port.CellsAt(cf, (prevfr * CfStride) + CfX1));
                            emon.Port.CellsPush(dbg, Evidence.LnGet(lt, prev, Evidence.LhX1()));
                            emon.Port.CellsPush(dbg, emon.Port.CellsAt(cf, (prevfr * CfStride) + CfCount));
                            if (score >= JoinMin) {
                                cont = 1;
                            }
                            if (Table.TbDueFor(tb, tcur, p, PaYmid2(lt, b), lt, b)) {
                                cont = 0;
                            }
                        }
                        if (Initial.InRow(lt, b) >= 0) {
                            cont = 0;
                        }
                        if (cont == 0) {
                            ty = Evidence.LnGet(lt, b, Evidence.LhY0());
                            beforePage = 0;
                            if (i == r) {
                                beforePage = p;
                            }
                            pend = PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, i, ty, beforePage, hc);
                            if ((i == r) && (p > 1)) {
                                PaMilestone(nodes, p, hc);
                            }
                            if (i == r) {
                                pend = PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, i, ty, 0, hc);
                            }
                            tcur = PaTables(tb, tcur, p, PaYmid2(lt, b), b, wd, lt, et, tc, tw, tq, nodes, attrs, regions, text, raw, tmp, ledger, hc);
                            PaFragOpen(fr, lt, p, b, 0);
                            PaIniStart(wd, lt, et, raw, fr, ii, b);
                        } else {
                            PaJoin(wd, lt, et, raw, b);
                            rs = emon.Port.CellsLen(raw);
                            PaFragOpen(fr, lt, p, b, rs);
                        }
                        open = 1;
                        PaAddLine(wd, lt, et, raw, b, hc, fr);
                        PaAlAdd(wd, lt, al, b, emon.Port.CellsAt(cf, (i * CfStride) + CfX0), emon.Port.CellsAt(cf, (i * CfStride) + CfX1));
                        prev = b;
                        prevfr = i;
                        cont = 1;
                        while (cont < cnt) {
                            b = emon.Port.CellsAt(lo, first + cont);
                            if (Table.TbClaimed(lt, b) == 0) {
                                if ((Initial.InRow(lt, b) >= 0) || (PaNewPar(wd, lt, et, prev, b, med, mg, hc) || Table.TbDueFor(tb, tcur, p, PaYmid2(lt, b), lt, b))) {
                                    ty = Evidence.LnGet(lt, b, Evidence.LhY0());
                                    pend = PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, i, ty, 0, hc);
                                    tcur = PaTables(tb, tcur, p, PaYmid2(lt, b), b, wd, lt, et, tc, tw, tq, nodes, attrs, regions, text, raw, tmp, ledger, hc);
                                    PaFragOpen(fr, lt, p, b, 0);
                                    PaIniStart(wd, lt, et, raw, fr, ii, b);
                                } else {
                                    PaJoin(wd, lt, et, raw, b);
                                    PaFragExtend(fr, lt, b);
                                }
                                PaAddLine(wd, lt, et, raw, b, hc, fr);
                                PaAlAdd(wd, lt, al, b, emon.Port.CellsAt(cf, (i * CfStride) + CfX0), emon.Port.CellsAt(cf, (i * CfStride) + CfX1));
                                prev = b;
                            }
                            cont += 1;
                        }
                    }
                    i += 1;
                }
                if (Table.TbDue(tb, tcur, p, PaAll)) {
                    pend = PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, nf, 1000000000, 0, hc);
                    open = 0;
                    prev = -1;
                    tcur = PaTables(tb, tcur, p, PaAll, -1, wd, lt, et, tc, tw, tq, nodes, attrs, regions, text, raw, tmp, ledger, hc);
                }
            }
            p += 1;
        }
        PaClose(wd, lt, et, nodes, attrs, regions, text, raw, tmp, fr, al, ii, cf, lo, gp, med, pend, nf, 1000000000, 0, hc);
        Align.AlPass(nodes, attrs, al, tm);
        return 0;
    }
    internal static int PaDumpNum(System.Text.StringBuilder t, int v) {
        emon.Port.TextCp(t, 32);
        emon.Port.TextI32(t, v);
        return 0;
    }
    public static int PaDump(System.Text.StringBuilder t, emon.Port.Cells cf, emon.Port.Cells dbg) {
        // The column stage's evidence as debug lines (SPEC 10.1.1; D163, D164), from what `pa-build` was given:
        // one line `F page band col role x0 y0 x1 y1 first count assoc` per column fragment (the cut tree's leaves,
        // in reading order, body fragments first; centipoints, `first`/`count` index the stage's line list) and one
        // `J fragment a b score` per join decision, in the order made (lines separated by a newline, none after the last) (`a`, `b` rows of the stage's lines, `score` the
        // points against `JOIN_MIN`). Not a contract.
        int nf = emon.Port.CellsLen(cf) / CfStride;
        int nj = emon.Port.CellsLen(dbg) / 8;
        int r = 0;
        int f = 0;
        int j = 0;
        int k = 0;
        while (r < nf) {
            if (k > 0) {
                emon.Port.TextCp(t, 10);
            }
            k += 1;
            emon.Port.TextAscii(t, "F");
            f = 0;
            while (f < 11) {
                PaDumpNum(t, emon.Port.CellsAt(cf, (r * CfStride) + f));
                f += 1;
            }
            r += 1;
        }
        while (j < nj) {
            if (k > 0) {
                emon.Port.TextCp(t, 10);
            }
            k += 1;
            emon.Port.TextAscii(t, "J");
            f = 0;
            while (f < 4) {
                PaDumpNum(t, emon.Port.CellsAt(dbg, (j * 8) + f));
                f += 1;
            }
            j += 1;
        }
        return 0;
    }
}
